      "description": "Mine the lectern using the wooden axe provided. The lectern will drop as an item.",
      "task_type": "mine",
      "target_block": "lectern",
      "rules": [
        {
          "rule_type": "inventory_has",
          "parameters": {
            "item": "lectern",
            "min_count": 1,
            "description": "Player must have a lectern item in inventory after mining it"
          }
        },
        {
          "rule_type": "voxel_count_in_box",
          "parameters": {
            "block_type": "lectern",
            "box_min": [-3, 1, 2],
            "box_max": [-1, 2, 4],
            "expected_count": 0,
            "description": "The lectern block must no longer exist at its original location"
          }
        }
